        getRate: vi.fn<(region: string) => Promise<number>>().mockResolvedValue(0.10),
      };
      const cart = new Cart({
        discountPolicy: discount,
        shippingCalculator: shipping,
        region: "US-CA",
      });
      cart.add(productA, 1); // subtotal 1000, discount 200, discounted 800
      const result = await cart.checkout({ asyncTaxProvider });
      // tax = floor(800 * 0.10) = 80
      expect(result.totals.taxCents).toBe(80);
      expect(result.totals.shippingCents).toBe(500);
      // total = 800 + 80 + 500 = 1380
      expect(result.totals.totalCents).toBe(1380);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("combines priceFetcher, inventoryChecker, and asyncTaxProvider", async () => {
      const cart = new Cart({ region: "FR" });
      cart.add(productA, 2);
      cart.add(productB, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn<(id: string) => Promise<number>>()
          .mockResolvedValueOnce(500)  // productA: 500
          .mockResolvedValueOnce(3000), // productB: 3000
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn<(id: string, qty: number) => Promise<InventoryDecision>>().mockResolvedValue({
          available: true,
          availableQuantity: 100,
        }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn<(region: string) => Promise<number>>().mockResolvedValue(0.20),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // subtotal = 500*2 + 3000*1 = 4000 (no discount by default)
      expect(result.totals.subtotalCents).toBe(4000);
      // tax = floor(4000 * 0.20) = 800
      expect(result.totals.taxCents).toBe(800);
      expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
    });

    it("propagates asyncTaxProvider rejection", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn<(region: string) => Promise<number>>().mockRejectedValue(new Error("tax service down")),
      };
      const cart = new Cart();
      cart.add(productA, 1);
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("tax service down");
    });

    it("propagates priceFetcher rejection", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn<(id: string) => Promise<number>>().mockRejectedValue(new Error("price API error")),
      };
      const cart = new Cart();
      cart.add(productA, 1);
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow("price API error");
    });

    it("first inventory denial wins (stops at first failing line)", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 1);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn<(id: string, qty: number) => Promise<InventoryDecision>>()
          .mockResolvedValueOnce({ available: false, reason: "product A gone" })
          .mockResolvedValueOnce({ available: true }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.unreachable("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        expect((err as InventoryError).productId).toBe("a");
      }
      // Only the first product was checked
      expect(inventoryChecker.check).toHaveBeenCalledTimes(1);
    });
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0, 0],
    [1000, 0],
    [-500, 0],
    [999999, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "percent must be between 0 and 100"],
      [101, "percent must be between 0 and 100"],
      [NaN, "percent must be between 0 and 100"],
      [Infinity, "percent must be between 0 and 100"],
    ])("rejects out-of-range percent %s", (percent, msg) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
    });

    it("accepts boundary values 0 and 100", () => {
      expect(() => new PercentageDiscountPolicy(0)).not.toThrow();
      expect(() => new PercentageDiscountPolicy(100)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it.each([
      [10, 1000, 100],
      [50, 1000, 500],
      [100, 1000, 1000],
      [0, 1000, 0],
      [33, 1000, 330],
      [10, 999, 99], // floors: 999 * 10 / 100 = 99.9 → 99
    ])("%i%% of %i cents = %i", (percent, subtotal, expected) => {
      const policy = new PercentageDiscountPolicy(percent);
      expect(policy.computeDiscountCents(subtotal)).toBe(expected);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-1000)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("caps discount at subtotal when amount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(2000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns full amount when subtotal exceeds amount", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns exact amount when equal to subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(1000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // 100
      const p2 = new FixedAmountDiscountPolicy(200); // 200
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10);
      const composite = new CompositeDiscountPolicy([p1], "sum");
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10);
      const composite = new CompositeDiscountPolicy([p1], "sum");
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("can produce a total exceeding the subtotal (caller clamps)", () => {
      const p1 = new FixedAmountDiscountPolicy(700);
      const p2 = new FixedAmountDiscountPolicy(600);
      // sum mode: min(700,1000) + min(600,1000) = 700 + 600 = 1300
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      expect(composite.computeDiscountCents(1000)).toBe(1300);
    });

    it("clamps negative child discount to 0 before summing", () => {
      // A NoDiscountPolicy always returns 0, which is >= 0 so no clamping needed
      const p1 = new NoDiscountPolicy();
      const p2 = new FixedAmountDiscountPolicy(500);
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      expect(composite.computeDiscountCents(1000)).toBe(500);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially against remaining subtotal", () => {
      // 10% of 1000 = 100, remaining = 900; fixed 200 capped to min(200,900) = 200
      const p1 = new PercentageDiscountPolicy(10);
      const p2 = new FixedAmountDiscountPolicy(200);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("stops accumulating when remaining reaches 0", () => {
      const p1 = new FixedAmountDiscountPolicy(1000);
      const p2 = new FixedAmountDiscountPolicy(500);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      // first: min(1000,1000) = 1000, remaining=0; second: min(500,0)=0
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("order matters: larger discount first yields different total", () => {
      const big = new PercentageDiscountPolicy(50);
      const small = new PercentageDiscountPolicy(10);

      const bigFirst = new CompositeDiscountPolicy([big, small], "chain");
      const smallFirst = new CompositeDiscountPolicy([small, big], "chain");

      // big first: 50% of 1000 = 500, remaining 500, 10% of 500 = 50 → total 550
      expect(bigFirst.computeDiscountCents(1000)).toBe(550);
      // small first: 10% of 1000 = 100, remaining 900, 50% of 900 = 450 → total 550
      expect(smallFirst.computeDiscountCents(1000)).toBe(550);
    });

    it("returns 0 for zero subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10);
      const composite = new CompositeDiscountPolicy([p1], "chain");
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });

  it("defaults to sum mode", () => {
    const p1 = new FixedAmountDiscountPolicy(100);
    const p2 = new FixedAmountDiscountPolicy(200);
    const composite = new CompositeDiscountPolicy([p1, p2]);
    expect(composite.computeDiscountCents(1000)).toBe(300);
  });
});

